import{_ as t,l,o as e,c as r,v as i,p as s,x as o,d as A,i as E,S as d}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"全球价值链","description":"","frontmatter":{"title":"全球价值链","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/global-value-chains.md","filePath":"econ/global-value-chains.md","lastUpdated":1789023840000}'),p={name:"econ/global-value-chains.md"};function h(c,a,m,B,_,u){const n=l("Mermaid");return e(),r("div",null,[a[1]||(a[1]=i('<h1 id="全球价值链" tabindex="-1">全球价值链 <a class="header-anchor" href="#全球价值链" aria-label="Permalink to &quot;全球价值链&quot;">​</a></h1><div class="epigraph"><p>出口里嵌着进口中间品；按总额记账会重复计算跨境次数，按增加值记账才会看见谁真正创造了价值、关税如何沿链放大。</p><footer>—— Hummels, Ishii and Yi, JIE 2001；Koopman, Wang and Wei, AER 2014；Antràs 价值链综述</footer></div><p><a href="/econ/trade-agreements">上一课</a>把壁垒写成最终品关税合约。本课缺口是生产被切开：全球价值链（GVC）。China shock 下一课把进口竞争落到地区劳动市场；本课先钉增加值贸易与有效保护。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Hummels–Ishii–Yi 的垂直专业化：出口中的进口投入份额上升。总额出口 \\(X\\) 可以很大，国内增加值 \\(VA\\) 小（加工贸易）。Koopman–Wang–Wei：把双边总额拆成国内 VA、返回的 VA、外国 VA、纯重复计算。缺口不是否定引力——总额仍服从引力——而是：福利、关税、顺差的含义要换口径。对美「中国顺差」用总额夸大中国 VA，用增加值会把东亚中间品供应算进来。</p><p><span class="marginnote">有效保护率：对最终品关税高、对中间品关税低，则国内加工的有效保护高于名义税率。价值链上，中间品税沿链叠加（Yi 的放大）。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>投入产出：世界 ICIO 表（WIOD、OECD TiVA）做增加值分解。理论：Antràs–Chor 把任务排序与合约摩擦写成谁做哪一段。贸易协定的原产地规则在 FTA 里决定能否用特惠——价值链越碎，原产地越苛刻，特惠越空。计量：不要用总额进口当「中国冲击」而不看投入产出（后课 ADH 用的是通勤区对进口的暴露，已是行业，不是 VA 全拆，但机制要意识中间品）。</p>',8)),(e(),s(d,null,{default:o(()=>[E(n,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20GROSS%5B%22%E6%80%BB%E9%A2%9D%E5%87%BA%E5%8F%A3%22%5D%20--%3E%20DBL%5B%22%E9%87%8D%E5%A4%8D%E8%AE%A1%E7%AE%97%E8%B7%A8%E5%A2%83%22%5D%0A%20%20VA%5B%22%E5%A2%9E%E5%8A%A0%E5%80%BC%E5%87%BA%E5%8F%A3%22%5D%20--%3E%20WHO%5B%22%E8%B0%81%E5%88%9B%E9%80%A0%E4%BB%B7%E5%80%BC%22%5D%0A%20%20TAR%5B%22%E4%B8%AD%E9%97%B4%E5%93%81%E5%85%B3%E7%A8%8E%22%5D%20--%3E%20AMP%5B%22%E6%B2%BF%E9%93%BE%E6%94%BE%E5%A4%A7%22%5D%0A%20%20ROO%5B%22%E5%8E%9F%E4%BA%A7%E5%9C%B0%22%5D%20--%3E%20FTA%5B%22%E7%89%B9%E6%83%A0%E8%83%BD%E5%90%A6%E8%90%BD%E5%9C%B0%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[A(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=i('<p>与 Melitz：企业不仅选择是否出口最终品，还选择离岸哪些任务——下一课 Grossman–Rossi-Hansberg。本课先给会计。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>机制是任务的可分与合约。运输与协调成本下降使切片变细（Yi）。产权与 hold-up 决定是企业内 FDI 还是臂长外包（Antràs）。关税按总额课征时，同一增加值被多次征税，保护与惩罚都放大。这改变最优关税与协定设计：中间品自由化往往比最终品更「顺价值链」。</p><p>与经常账户：VA 口径改的是谁对谁的双边顺差叙事，不改一国总 CA 的国民账户——<a href="/econ/open-ca">开放会计</a>仍是 \\(S-I\\)。双边「附加值顺差」是分解，不是第三个恒等。</p><p><span class="marginnote">不要用 GVC 取消比较优势：切片之后，比较优势用在任务上，而不是整辆汽车上。李嘉图仍在，对象变细。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把某年版 TiVA 表抄成结论。不写具体公司供应链管理。China shock 下一课是劳动市场设计，会用到行业进口，但输家故事要允许「出口商用了进口中间品而扩张」。离岸任务课把理论写全。不要用总额顺差当贸易战的充分统计。</p><p>后课默认：总额与增加值分叉；关税沿链放大；原产地约束特惠。国民账户 \\(CA\\) 仍是总储蓄投资。任务层面的比较优势下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>垂直专业化：出口含进口投入；总额重复计算。</li><li>增加值分解才看见价值来源与双边叙事。</li><li>中间品关税沿链放大；有效保护 ≠ 名义税率。</li><li>原产地规则决定 FTA 在碎链上是否空转。</li><li>出处：Hummels, Ishii and Yi, <em>JIE</em> 2001；Koopman, Wang and Wei, <em>AER</em> 2014；Antràs。</li></ul>',10))])}const T=t(p,[["render",h]]);export{f as __pageData,T as default};
